+            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
+
+        // With small datasets, train on all data and evaluate on training set for metrics
+        _model = pipeline.Fit(dataView);
+
+        var predictions = _model.Transform(dataView);
+        var mlMetrics = _mlContext.MulticlassClassification.Evaluate(predictions);
+        _metrics = new EvaluationMetrics
+        {
+            MacroAccuracy = mlMetrics.MacroAccuracy,
+            MicroAccuracy = mlMetrics.MicroAccuracy,
+            LogLoss = mlMetrics.LogLoss,
+            LogLossReduction = mlMetrics.LogLossReduction
+        };
+
+        // Extract the category label ordering from the trained model's key-value mapping
+        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
+        predictions.Schema["PredictedLabel"]
+            .GetKeyValues(ref labelBuffer);
+
+        _categoryLabels = labelBuffer.DenseValues()
+            .Select(v => v.ToString())
+            .ToArray();
+
+        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
+    }
+
+    public PredictionResponse Predict(TicketRequest request)
+    {
+        var ticketData = new TicketData
+        {
+            Subject = request.Subject,
+            Description = request.Description,
+            Priority = request.Priority
+        };
+
+        var prediction = _predictionEngine.Predict(ticketData);
+
+        var confidenceScores = new Dictionary<string, float>();
+        for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
+        {
+            confidenceScores[_categoryLabels[i]] = prediction.Score[i];
+        }
+
+        return new PredictionResponse
+        {
+            PredictedCategory = prediction.Category,
+            ConfidenceScores = confidenceScores
+        };
+    }
+
+    public EvaluationMetrics GetMetrics() => _metrics;
+}
